"""Verify an attained raised indexing stroke and unsupported release controls."""
import argparse,copy,hashlib,json,pathlib,sys
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def run(a):
 load=lambda p:json.loads(p.read_bytes());source=load(a.source);c=load(a.packet/'native-raised-index-contract.json');lc=load(a.packet/'native-static-lift-hold-contract.json');sys.path[:0]=[str(a.project/f'sim/{x}') for x in ['pressure','integrated','drivetrain','actuation','acquisition']]
 from native_static_lift import NativeStaticLift
 from verify_native_static_lift import difference
 def model():return NativeStaticLift(source['initial'],load(a.project/'sim/drivetrain/config.json'),load(a.project/'sim/acquisition/free-planar-config.json')['model'],load(a.project/'cad/assembly/intake_components.json'),load(a.packet/'native-pressure-binding.json'),load(a.project/'sim/actuation/config.json'),load(a.packet/'native-pressure-lift-contract.json'),friction_mu=.6,solver_tolerance=lc['solverGapToleranceJ'],solver_iterations=lc['solverMaxIterations'])
 runs={};summaries=[];replays=[]
 for name in ['native-raised-index-half','native-raised-index-quarter','native-raised-release-half','native-raised-release-quarter']:
  path=a.packet/name/'receipt.json';r=load(path);runs[name]=r;release='release' in name;assert r['initial']==source['final'];assert r['inputs']['sourceReceipt']==sha(a.source)
  for key,filename in [('runner' if not release else 'producer','continue_native_raised_index.py' if not release else 'run_native_raised_release.py'),('model','native_static_lift.py'),('friction','native_dry_friction.py'),('binding','native-pressure-binding.json'),('liftContract','native-static-lift-hold-contract.json'),('baseContract','native-pressure-lift-contract.json'),('contract','native-raised-release-contract.json' if release else 'native-raised-index-contract.json')]:assert r['inputs'][key]==sha(a.packet/filename),(name,key)
  m=model();m.friction_mu=0. if release else .6;rows=r['trace'];previous=r['initial'];before=[];currents=[];peak=0.
  for i,row in enumerate(rows):
   assert abs(row['timeS']-r['initial']['timeS']-(i+1)*r['stepS'])<1e-9;cmd=r['command'] if release else r['events'][i//round(.01/r['stepS'])]['command'];de,pe,ae=m.electrical(previous,row['busV'],cmd);currents.extend(x['currentA'] for x in pe);peak=max(peak,*(abs(x['currentA']) for x in ae['motors']));assert all(abs(x['currentA'])<=40 for x in pe+ae['motors']);assert abs(row['sourcePowerResidualW'])<1e-8;assert row['friction']['maximumConeExcessNs']<1e-12 and row['friction']['gapJ']<=1e-12;before.append(previous);previous=row['state']
  for i in sorted(set([0,len(rows)//2,len(rows)-1])):
   m.s=copy.deepcopy(before[i]);m.ledger=copy.deepcopy(m.s['ledger']);cmd=r['command'] if release else r['events'][i//round(.01/r['stepS'])]['command'];again=m.step(r['stepS'],cmd);error=difference(again,rows[i]);assert error<1e-12;replays.append(dict(run=name,step=i+1,maximumDifference=error))
  s=r['final'];rel=s['note']['p'][0]-s['chassis']['x'];rv=s['note']['v'][0]-s['chassis']['vx'];initial_rel=r['initial']['note']['p'][0]-r['initial']['chassis']['x'];floor=[x for x in rows if x['floorForceN'][2]>0];summary=dict(name=name,outcome=r['outcome'],reason=r['reason'],stepS=r['stepS'],acceptedSteps=len(rows),durationS=s['timeS']-r['initial']['timeS'],relativeDisplacementM=rel-initial_rel,finalRelativeSpeedMps=rv,finalNoteRiseM=s['noteZ']-.0254,maximumRelativeVerticalDriftM=max(abs(x['state']['noteZ']-x['state']['zPivot']) for x in rows),firstFloorContactElapsedS=floor[0]['timeS']-r['initial']['timeS'] if floor else None,minimumPinchCurrentA=min(currents),maximumPinchCurrentA=max(currents),peakLiftPitchCurrentA=peak,maximumIncrementalEnergyResidualJ=max(abs(x['energyJ']['residual']-r['inheritedResidualJ']) for x in rows),receiptSha256=sha(path))
  if not release:
   assert r['initialMechanicalDifferenceJ']==0 and r['lastSourceStateReplayedExactly'];gate=c['gate'];window=[x for x in rows if x['timeS']>=s['timeS']-gate['lastWindowS']-1e-10];summary['finalPositionErrorM']=rel-r['targetRelativeXM'];summary['lastWindowMaximumFloorForceN']=max(abs(x['floorForceN'][2]) for x in window);summary['gatePassed']=r['outcome']=='HORIZON' and abs(summary['finalPositionErrorM'])<=gate['maximumFinalPositionErrorM'] and summary['finalNoteRiseM']>=gate['minimumFinalNoteRiseM'] and summary['maximumRelativeVerticalDriftM']<=gate['maximumRelativeVerticalDriftM'] and abs(rv)<=gate['maximumFinalRelativeSpeedMps'] and summary['lastWindowMaximumFloorForceN']==0
  summaries.append(summary)
 first=runs['native-raised-index-half'];second=runs['native-raised-index-quarter'];fine={round(x['timeS'],8):x for x in second['trace']};dp=dv=0.
 for x in first['trace']:
  y=fine[round(x['timeS'],8)];u,v=x['state'],y['state'];dp=max(dp,abs(u['note']['p'][0]-v['note']['p'][0]),abs(u['noteZ']-v['noteZ']),abs(u['zPivot']-v['zPivot']));dv=max(dv,abs(u['note']['v'][0]-v['note']['v'][0]),abs(u['noteVz']-v['noteVz']),abs(u['vPivot']-v['vPivot']))
 return dict(schema='native-raised-index-verification/1',scriptSha256=sha(pathlib.Path(__file__)),integrityChecksPassed=True,sourceStateAndLedgerExact=True,mechanicalJoinDifferenceJ=first['initialMechanicalDifferenceJ'],sourceReplayResidualDifferenceJ=first['lastSourceResidualDifferenceJ'],runs=summaries,comparison=dict(maximumPositionDifferenceM=dp,maximumVelocityDifferenceMps=dv,withinLiftContractBounds=dp<=lc['comparisonBounds']['positionM'] and dv<=lc['comparisonBounds']['velocityMps']),selectedStepReplays=replays,acceptance=False,fullLauncherFeed=False,hardwareValidated=False,limits=['A4mm raised indexing request is not a verified launcher handoff or full feed path','Both local feed steps start from the same attained half-step2s hold','Zero-friction release deliberately changes only friction after the attained hold; it is a counterexample, not calibration','Native assembly clearance/mass/transmission and same-law fresh acquisition remain unverified'])
if __name__=='__main__':
 p=argparse.ArgumentParser()
 for name in ['packet','project','source','output']:p.add_argument('--'+name,type=pathlib.Path,required=True)
 a=p.parse_args();assert not a.output.exists();r=run(a);a.output.write_text(json.dumps(r,indent=2)+'\n',encoding='utf-8',newline='\n');print(json.dumps({k:v for k,v in r.items() if k!='selectedStepReplays'},indent=2))
